/* Bare-metal test driver for the xtc-generated matmul — shared by the three
 * dtype variants (i8/i16/i32, selected via -DMATMUL_ELT in xtc_crt.h).
 *
 * matmul (C = A x B) is generated by ../gen_matmul.py with I=4, J=32, K=128,
 * i.e. the schedule of test_xtc_i32.py with a reduction depth that fits the
 * Z80's 64K address space.
 *
 * Data:
 *   A[i][k] = i + 1  (row constant)
 *   B[k][j] = j + 1  (column constant)
 * so the exact result is C[i][j] = (i + 1) * (j + 1) * K.  The reference is
 * computed in 32-bit arithmetic and narrowed with the element-type cast,
 * i.e. every comparison is modulo 2^bits — int8/int16 accumulate with
 * wrap-around by construction (arith on iN wraps in MLIR, and SDCC narrows
 * to the same two's-complement result; for i32 the value is exact anyway).
 * Every element of C depends on every k-step, so any scheduling, indexing
 * or accumulation bug shows up as a mismatch.
 *
 * Console output goes to I/O port 0x01 (putc in crt0.s), as in hello_world/.
 */

#include "xtc_crt/xtc_crt.h"

#define I 4
#define J 32
#define K 128

extern void putc(char c);
extern void matmul(matmul_elt *a, matmul_elt *b, matmul_elt *c);

static matmul_elt A[I][K];
static matmul_elt B[K][J];
static matmul_elt C[I][J];

static void puts_raw(const char *s) {
  while (*s)
    putc(*s++);
}

static void put_hex8(unsigned int v) {
  static const char digits[] = "0123456789ABCDEF";
  putc(digits[(v >> 4) & 0xF]);
  putc(digits[v & 0xF]);
}

static void put_hex32(int32_t value) {
  unsigned long v = (unsigned long)value;
  put_hex8((unsigned int)((v >> 24) & 0xFF));
  put_hex8((unsigned int)((v >> 16) & 0xFF));
  put_hex8((unsigned int)((v >> 8) & 0xFF));
  put_hex8((unsigned int)(v & 0xFF));
}

static void put_dec(unsigned int v) {
  char buf[6];
  int n = 0;
  do {
    buf[n++] = (char)('0' + v % 10);
    v /= 10;
  } while (v && n < 5);
  while (n)
    putc(buf[--n]);
}

void main(void) {
  for (int i = 0; i < I; i++)
    for (int k = 0; k < K; k++)
      A[i][k] = i + 1;

  for (int k = 0; k < K; k++)
    for (int j = 0; j < J; j++)
      B[k][j] = j + 1;

  matmul((matmul_elt *)A, (matmul_elt *)B, (matmul_elt *)C);

  unsigned int mismatches = 0;
  int fi = 0, fj = 0;
  int32_t fgot = 0, fexp = 0;
  for (int i = 0; i < I; i++) {
    for (int j = 0; j < J; j++) {
      /* Exact reference in 32 bits, then narrowed like the kernel: every
       * comparison is modulo the element type. */
      int32_t expected = (int32_t)(i + 1)     * (j + 1) * K;
      matmul_elt narrowed = (matmul_elt)expected;
      if (C[i][j] != narrowed) {
        if (mismatches == 0) {
          fi = i;
          fj = j;
          fgot = C[i][j];
          fexp = narrowed;
        }
        mismatches++;
      }
    }
  }

  if (mismatches == 0) {
    puts_raw("PASS: matmul ");
    put_dec(I);
    putc('x');
    put_dec(K);
    putc('x');
    put_dec(J);
    putc(' ');
    puts_raw("i");
    put_dec(sizeof(matmul_elt) * 8);
    puts_raw(" on Z80 (sdcc + xtc)\r\n");
  } else {
    puts_raw("FAIL: mismatches=");
    put_dec(mismatches);
    puts_raw(" first at i=");
    put_dec((unsigned int)fi);
    puts_raw(" j=");
    put_dec((unsigned int)fj);
    puts_raw(" got=0x");
    put_hex32(fgot);
    puts_raw(" expected=0x");
    put_hex32(fexp);
    puts_raw("\r\n");
  }
}
